sys_script.script:
function onBefore(current, previous) {
    var prefix = 'BUD';
    var maxDigits = 7;
    var nextNum = 1001;

    var gr = new GlideRecord('x_1962601_budget_t_budget');
    gr.addNotNullQuery('number');
    gr.addQuery('number', '!=', '');
    gr.orderByDesc('number');
    gr.setLimit(1);
    gr.query();
    if (gr.next()) {
        var lastNumber = gr.getValue('number');
        if (lastNumber && lastNumber.indexOf(prefix) === 0) {
            var numericPart = parseInt(lastNumber.substring(prefix.length), 10);
            if (!isNaN(numericPart)) {
                nextNum = numericPart + 1;
            }
        }
    }

    var paddedNum = String(nextNum);
    while (paddedNum.length < maxDigits) {
        paddedNum = '0' + paddedNum;
    }
    current.number = prefix + paddedNum;
}
